private const val VIEWPORT_W = 13.99993896484375f
private const val VIEWPORT_H = 14f

private fun buildIcon(icon: AegisIcon): ImageVector =
    ImageVector.Builder(
        name = icon.name.lowercase(),
        defaultWidth = 14.dp,
        defaultHeight = 14.dp,
        viewportWidth = VIEWPORT_W,
        viewportHeight = VIEWPORT_H,
    ).apply {
        path(
            name = icon.name.lowercase() + "-path",
            fill = SolidColor(Color.Black),
            pathData = addPathNodes(icon.pathData),
        )
    }.build()


