private val SlidersHorizontalIcon: ImageVector by lazy { buildIcon(AegisIcon.SlidersHorizontal) }
private val ShieldIcon: ImageVector by lazy { buildIcon(AegisIcon.Shield) }
private val RotateCcwIcon: ImageVector by lazy { buildIcon(AegisIcon.RotateCcw) }

/** Non-composable access to the platform [ImageVector] backing an [AegisIcon]. */
fun aegisIconVector(icon: AegisIcon): ImageVector = when (icon) {
        AegisIcon.ChevronRight -> ChevronRightIcon
        AegisIcon.KeyRound -> KeyRoundIcon
        AegisIcon.RefreshCw -> RefreshCwIcon
        AegisIcon.Copy -> CopyIcon
        AegisIcon.ShieldCheck -> ShieldCheckIcon
        AegisIcon.Settings -> SettingsIcon
        AegisIcon.Lock -> LockIcon
        AegisIcon.ChevronLeft -> ChevronLeftIcon
        AegisIcon.FileText -> FileTextIcon
        AegisIcon.Bell -> BellIcon
        AegisIcon.Share2 -> Share2Icon
        AegisIcon.ScanFace -> ScanFaceIcon
        AegisIcon.Check -> CheckIcon
        AegisIcon.User -> UserIcon
        AegisIcon.Trash2 -> Trash2Icon
        AegisIcon.CreditCard -> CreditCardIcon
        AegisIcon.Search -> SearchIcon
        AegisIcon.Plus -> PlusIcon
        AegisIcon.HardDrive -> HardDriveIcon
        AegisIcon.Globe -> GlobeIcon
        AegisIcon.Eye -> EyeIcon
        AegisIcon.X -> XIcon
        AegisIcon.SlidersHorizontal -> SlidersHorizontalIcon
        AegisIcon.Shield -> ShieldIcon
        AegisIcon.RotateCcw -> RotateCcwIcon
}

/**
 * Draws an [AegisIcon] tinted with [tint]. The vector artwork is 14dp; callers
 * scale it via [size] as the layout requires.
 */
@Composable
fun AegisIconGraphic(
    icon: AegisIcon,
    contentDescription: String?,
    modifier: Modifier = Modifier,
    tint: Color = Color.Black,
    size: Dp = 14.dp,
) {
    Image(
        painter = rememberVectorPainter(aegisIconVector(icon)),
        contentDescription = contentDescription,
        modifier = modifier.size(size),
        colorFilter = ColorFilter.tint(tint),
    )
}
